package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class SimpleType_construct_TriageGen0Test {

    @Test
    public void testConstruct_ValidClass() {
        Class<?> validClass = String.class;
        SimpleType result = SimpleType.construct(validClass);
        assertNotNull(result);
        assertEquals(validClass, result.getRawClass());
    }

    @Test
    public void testConstruct_ValidInteger() {
        Class<?> validClass = Integer.class;
        SimpleType result = SimpleType.construct(validClass);
        assertNotNull(result);
        assertEquals(validClass, result.getRawClass());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstruct_MapClass() {
        SimpleType.construct(Map.class);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstruct_HashMap() {
        SimpleType.construct(HashMap.class);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstruct_CollectionClass() {
        SimpleType.construct(Collection.class);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstruct_List() {
        SimpleType.construct(List.class);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstruct_ArrayType() {
        SimpleType.construct(String[].class);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstruct_PrimitiveArray() {
        SimpleType.construct(int[].class);
    }

    @Test
    public void testConstruct_CustomClass() {
        class CustomClass {}
        SimpleType result = SimpleType.construct(CustomClass.class);
        assertNotNull(result);
        assertEquals(CustomClass.class, result.getRawClass());
    }
}
